insert into properties (id, building_id, reference_number, slug, title, teaser, description, category, categories, property_type, status, price_type, price_note, commission_free, commission_months, commission_note, features, area_range_min_sqm, area_range_max_sqm, expose_pdf_url, featured_rank, source, external_id) values (md5('property-16947')::uuid, md5('building-dammtorwall-7a-20354')::uuid, '16947', 'buero-oder-praxisflaeche-in-ruhiger-citylage-16947', 'Büro- oder Praxisfläche in ruhiger Citylage', 'Das ansprechende Neubaugebäude befindet sich in zentraler Innenstadtlage unweit des Gänsemarktes und der Binnenalster. Die Anbindung an den ÖPNV ist durch diverse U- Bahnstationen …', 'Das ansprechende Neubaugebäude befindet sich in zentraler Innenstadtlage unweit des Gänsemarktes und der Binnenalster. Die Anbindung an den ÖPNV ist durch diverse U- Bahnstationen und den in wenigen Gehminuten erreichten Dammtorbahnhof sehr gut. Vielseitige Einkaufsmöglichkeiten und ein abwechslungsreiches, gastronomisches Angebot unterstreichen die Attraktivität dieses Standortes. Die hochwertige Ausstattung der Fläche umfasst unter anderem außenliegenden Sonnenschutz, Doppelboden, isolierverglaste Schallschutzfenster, EDV-Verkabelung, Glastüren, eine Teeküche und betonkernaktivierte Decken, die für ein angenehmes Raumklima sorgen. Die zum Teil bodentiefen Fenster ermöglichen eine sehr gute Belichtung. Das gesamte Gebäude verfügt über eine behindertengerechte Erschließung zu der u.a. auch eine doppelte Aufzuganlage zählt. Die Bilder sind beispielhaft gewählt. PKW-Stellplätze können auf Anfrage angemietet werden.', 'buero-praxis', array['buero-praxis', 'lager-logistik']::property_category[], 'buero', 'published', 'qm', 'zzgl. NK u. MwSt.', true, null, 'Dieses Mietangebot ist courtagefrei für den Mieter bei Abschluss eines Mietvertrages mit einer festen Mietlaufzeit von mindestens 5 Jahren.', array['barrierefrei', 'erdgeschoss']::text[], null, null, 'https://www.buerohamburg.de/objects/pdf/BHI_16947.pdf', null, 'filemaker', '16947') on conflict (id) do nothing;
