insert into properties (id, building_id, reference_number, slug, title, teaser, description, category, categories, property_type, status, price_type, price_note, commission_free, commission_months, commission_note, features, area_range_min_sqm, area_range_max_sqm, expose_pdf_url, featured_rank, source, external_id) values (md5('property-24995')::uuid, md5('building-ludwigstrasse-12-20357')::uuid, '24995', 'modernes-bueroloft-in-der-schanze-24995', 'Modernes Büroloft in der Schanze', 'Die loftige und großzügig geschnittene Bürofläche befindet sich in der Steinway-Halle im Schanzenviertel nur wenige Meter von der U-Bahnstation Feldstraße entfernt. Zahlreiche …', 'Die loftige und großzügig geschnittene Bürofläche befindet sich in der Steinway-Halle im Schanzenviertel nur wenige Meter von der U-Bahnstation Feldstraße entfernt. Zahlreiche Einkaufsmöglichkeiten und diverse Cafés und Restaurants erhöhen die Attraktivität dieser lebendigen Stadtteillage. Die Ausstattung der lichtdurchfluteten Fläche umfasst aktuell Holzfußboden, zum Teil Glastrennelemente, eine gut ausgestattete und geräumige Teeküche und separate WC-Einheiten. Die weitere Ausstattung erfolgt in Absprache mit dem zukünftigen Mieter. Diese Innenbilder sind beispielhaft gewählt und stammen aus einer ähnlichen Fläche im Objekt. Pkw-Stellplätze können im Umfeld angemietet werden.', 'buero-praxis', array['buero-praxis']::property_category[], 'buero', 'published', 'qm', 'zzgl. NK u. MwSt.', false, 3, 'Dieses Mietangebot ist courtagepflichtig für den Mieter.*', '{}'::text[], 276, 561, 'https://www.buerohamburg.de/objects/pdf/BHI_24995.pdf', null, 'filemaker', '24995') on conflict (id) do nothing;
