insert into properties (id, building_id, reference_number, slug, title, teaser, description, category, categories, property_type, status, price_type, price_note, commission_free, commission_months, commission_note, features, area_range_min_sqm, area_range_max_sqm, expose_pdf_url, featured_rank, source, external_id) values (md5('property-23249')::uuid, md5('building-veritaskai-2-21079')::uuid, '23249', 'helle-ladenflaeche-im-ehemaligen-getreidespeicher-in-harburg-23249', 'Helle Ladenfläche im ehemaligen Getreidespeicher in Harburg', 'Der ehemalige Getreidespeicher, der äußert aufwendig und liebevoll zu einem modernen Bürogebäude mit integriertem Parkhaus umgebaut wurde, befindet sich direkt am Wasser, im …', 'Der ehemalige Getreidespeicher, der äußert aufwendig und liebevoll zu einem modernen Bürogebäude mit integriertem Parkhaus umgebaut wurde, befindet sich direkt am Wasser, im lebendigen und innovativen Bürostandort Channel Hamburg. Die Anbindung an den ÖPNV ist durch die S-Bahn und diversen Buslinien gegeben. Ein vielseitiges gastronomisches Angebot und Einkaufsmöglichkeiten liegen in unmittelbarer Nähe. Die helle Ladenfläche erstreckt sich vom Erdgeschoss bis ins Untergeschoss. Die Innenbilder sind dabei beispielhaft gewählt. Die weitere Ausstattung und Aufteilung erfolgt in Absprache mit dem zukünftigen Mieter. PKW- Stellplätze sind im Objekt vorhanden und können angemietet werden.', 'laden-gastro', array['laden-gastro']::property_category[], 'laden', 'published', 'qm', 'zzgl. NK u. MwSt.', false, 3.6, 'Dieses Mietangebot ist courtagepflichtig für den Mieter.*', array['erdgeschoss', 'wasserblick']::text[], 287, 514, 'https://www.buerohamburg.de/objects/pdf/BHI_23249.pdf', null, 'filemaker', '23249') on conflict (id) do nothing;
