insert into properties (id, building_id, reference_number, slug, title, teaser, description, category, categories, property_type, status, price_type, price_note, commission_free, commission_months, commission_note, features, area_range_min_sqm, area_range_max_sqm, expose_pdf_url, featured_rank, source, external_id) values (md5('property-15705')::uuid, md5('building-neuer-wall-41-20354')::uuid, '15705', 'exklusive-bueroflaechen-in-bester-citylage-15705', 'Exklusive Büroflächen in bester Citylage', 'In bester Innenstadtlage, zwischen Neuem Wall und Alsterfleet, befindet sich dieses imposante Büro- und Geschäftsgebäude. Die Binnenalster, der Rathausmarkt sowie diverse …', 'In bester Innenstadtlage, zwischen Neuem Wall und Alsterfleet, befindet sich dieses imposante Büro- und Geschäftsgebäude. Die Binnenalster, der Rathausmarkt sowie diverse Verbindungen zum ÖPNV befinden sich in direkter Umgebung. Die modernen Mieteinheiten werden über einen repräsentativen Eingangsbereich erschlossen und verfügen u.a. über Kühl- und Beleuchtungssysteme, Sonnenschutz, CAT-7-Verkabelung, Pantrys sowie getrennte WC-Einheiten und können in Absprache mit dem zukünftigen Mieter flexibel aufgeteilt und ausgestattet werden. PKW-Stellplätze können im Nachbargebäude angemietet werden. Diese Bilder sind beispielhaft gewählt.', 'buero-praxis', array['buero-praxis']::property_category[], 'buero', 'published', 'qm', 'zzgl. NK u. MwSt.', true, null, 'Dieses Mietangebot ist courtagefrei für den Mieter bei Abschluss eines Mietvertrages mit einer festen Mietlaufzeit von mindestens 5 Jahren.', array['barrierefrei', 'stellplaetze']::text[], 251, 602, 'https://www.buerohamburg.de/objects/pdf/BHI_15705.pdf', null, 'filemaker', '15705') on conflict (id) do nothing;
