insert into properties (id, building_id, reference_number, slug, title, teaser, description, category, categories, property_type, status, price_type, price_note, commission_free, commission_months, commission_note, features, area_range_min_sqm, area_range_max_sqm, expose_pdf_url, featured_rank, source, external_id) values (md5('property-19570')::uuid, md5('building-gruener-deich-1-3-20097')::uuid, '19570', 'frei-ab-sofort-helle-bueroflaeche-in-der-citysued-19570', 'Frei ab sofort: helle Bürofläche in der CitySüd', 'Das moderne Bürogebäude befindet sich in markanter Ecklage der City-Süd. Diverse gastronomische Angebote sowie die S-Bahn Station Hammerbrook befinden sich im direkten Umfeld und …', 'Das moderne Bürogebäude befindet sich in markanter Ecklage der City-Süd. Diverse gastronomische Angebote sowie die S-Bahn Station Hammerbrook befinden sich im direkten Umfeld und sind fußläufig in wenigen Minuten zu erreichen. Über den hellen Eingangsbereich mit zwei Aufzügen sind die jeweiligen Mieteinheiten zu erreichen, die in Absprache mit dem zukünftigen Nutzer aufgeteilt und ausgestattet werden. Zur derzeitigen Ausstattung gehört u.a. ein Teppichbodenbelag, Bodentanks für eine spätere Netzwerkverkabelung, Stehleuchten, getrennte WC-Einheiten, außenliegender Sonnenschutz sowie teilweise bodentiefe Fenster und eine EInbauküche. PKW-Stellplätze können zusätzlich angemietet werden.', 'buero-praxis', array['buero-praxis']::property_category[], 'buero', 'published', 'qm', 'zzgl. NK u. MwSt.', true, null, 'Dieses Mietangebot ist courtagefrei für den Mieter bei Abschluss eines Mietvertrages mit einer festen Mietlaufzeit von mindestens 5 Jahren.', array['stellplaetze']::text[], null, null, 'https://www.buerohamburg.de/objects/pdf/BHI_19570.pdf', null, 'filemaker', '19570') on conflict (id) do nothing;
