insert into properties (id, building_id, reference_number, slug, title, teaser, description, category, categories, property_type, status, price_type, price_note, commission_free, commission_months, commission_note, features, area_range_min_sqm, area_range_max_sqm, expose_pdf_url, featured_rank, source, external_id) values (md5('property-25442')::uuid, md5('building-stadthausbruecke-5-7-20355')::uuid, '25442', 'deutsch-japanisches-zentrum-im-herzen-der-stadt-25442', 'Deutsch-Japanisches-Zentrum im Herzen der Stadt', 'Das repräsentative Bürogebäude Deutsch-Japanisches-Zentrum befindet sich auf der Fleetinsel in bester Innenstadtlage. Nur wenige Meter entfernt befinden sich diverse Passagen mit …', 'Das repräsentative Bürogebäude Deutsch-Japanisches-Zentrum befindet sich auf der Fleetinsel in bester Innenstadtlage. Nur wenige Meter entfernt befinden sich diverse Passagen mit vielfältigen Einkaufsmöglichkeiten sowie zahlreiche Cafés und Restaurants. Eine sehr gute Verkehrsanbindung wird durch die U-Bahn-Stationen Stadthausbrücke und Rödingsmarkt sowie die nahe gelegene Station Jungfernstieg gesichert. Zur Ausstattung zählen u.a. Bodentanks, Leichtbauwände mit teilweise Glasausschnitten, Beleuchtungssysteme, getrennte WC-Einheiten sowie eine Pantry. Diese Innenbilder sind beispielhaft gewählt und stammen aus einer ähnlichen Fläche im Objekt. PKW-Stellplätze können im Umfeld angemietet werden.', 'buero-praxis', array['buero-praxis']::property_category[], 'buero', 'published', 'qm', 'zzgl. NK u. MwSt.', true, null, 'Dieses Mietangebot ist courtagefrei für den Mieter bei Abschluss eines Mietvertrages mit einer festen Mietlaufzeit von mindestens 5 Jahren.', array['barrierefrei', 'stellplaetze']::text[], null, null, 'https://www.buerohamburg.de/objects/pdf/BHI_25442.pdf', null, 'filemaker', '25442') on conflict (id) do nothing;
