insert into properties (id, building_id, reference_number, slug, title, teaser, description, category, categories, property_type, status, price_type, price_note, commission_free, commission_months, commission_note, features, area_range_min_sqm, area_range_max_sqm, expose_pdf_url, featured_rank, source, external_id) values (md5('property-23281')::uuid, md5('building-martinistrasse-64-20246')::uuid, '23281', 'helles-buero-im-gesundheitszentrum-am-uke-23281', 'Helles Büro im Gesundheitszentrum am UKE', 'Das Spectrum bildet eine Erweiterung des Gesundheitsparks rund um das UKE und beherbergt sowohl Einzelhandel wie auch Büro- und Praxisflächen. Auf dem Gelände vereinen sich alle …', 'Das Spectrum bildet eine Erweiterung des Gesundheitsparks rund um das UKE und beherbergt sowohl Einzelhandel wie auch Büro- und Praxisflächen. Auf dem Gelände vereinen sich alle Komponenten rund um das Thema Gesundheit und Medizin, neben Geschäften des täglichen Bedarfs finden sich auch niedergelassene Ärzte sowie Anbieter von medizinischen Heil- und Hilfsmitteln. Mehrere Buslinien sichern die Anbindung an die öffentlichen Verkehrsmittel, die Hamburger Innenstadt ist nur wenige Fahrminuten entfernt. Die Ausstattung der hellen Mietfläche umfasst u.a. einen Vinylboden in Holzoptik, außenliegenden Sonnenschutz, teilweise Glaselemente, eine großzügige Pantry sowie getrennte Sanitäreinheiten. Die weitere Aufteilung und Ausstattung erfolgt in Absprache mit dem zukünftigen Mieter. PKW-Stellplätze können in der hauseigenen Tiefgarage angemietet werden.', 'buero-praxis', array['buero-praxis']::property_category[], 'buero', 'published', 'qm', 'zzgl. NK u. MwSt.', true, null, 'Dieses Mietangebot ist courtagefrei für den Mieter bei Abschluss eines Mietvertrages mit einer festen Mietlaufzeit von mindestens 5 Jahren.', array['barrierefrei', 'stellplaetze']::text[], 300, 780, 'https://www.buerohamburg.de/objects/pdf/BHI_23281.pdf', null, 'filemaker', '23281') on conflict (id) do nothing;
