insert into properties (id, building_id, reference_number, slug, title, teaser, description, category, categories, property_type, status, price_type, price_note, commission_free, commission_months, commission_note, features, area_range_min_sqm, area_range_max_sqm, expose_pdf_url, featured_rank, source, external_id) values (md5('property-25588')::uuid, md5('building-grosser-burstah-45-20457')::uuid, '25588', 'hochwertig-ausgebaute-bueroflaeche-in-rathausnaehe-25588', 'Hochwertig ausgebaute Bürofläche in Rathausnähe', 'Das moderne Bürogebäude befindet sich zwischen Rödingsmarkt und Rathaus im Hamburger Börsenviertel in beliebter Geschäftslage. Die U- und S-Bahnstationen Rödingsmarkt und …', 'Das moderne Bürogebäude befindet sich zwischen Rödingsmarkt und Rathaus im Hamburger Börsenviertel in beliebter Geschäftslage. Die U- und S-Bahnstationen Rödingsmarkt und Stadthausbrücke sichern eine sehr gute Anbindung an das öffentliche Verkehrsnetz. Das attraktive Umfeld ist geprägt durch hochwertige Einzelhändler, alle Geschäfte des täglichen Bedarfs und einer Vielzahl gastronomischer Angebote. Die weitere Ausstattung und Aufteilung erfolgt in Absprache mit dem zukünftigen Mieter.', 'buero-praxis', array['buero-praxis']::property_category[], 'buero', 'published', 'qm', 'zzgl. NK u. MwSt.', true, null, 'Dieses Mietangebot ist courtagefrei für den Mieter bei Abschluss eines Mietvertrages mit einer festen Mietlaufzeit von mindestens 5 Jahren.', array['stellplaetze']::text[], 301, 586, 'https://www.buerohamburg.de/objects/pdf/BHI_25588.pdf', null, 'filemaker', '25588') on conflict (id) do nothing;
