insert into properties (id, building_id, reference_number, slug, title, teaser, description, category, categories, property_type, status, price_type, price_note, commission_free, commission_months, commission_note, features, area_range_min_sqm, area_range_max_sqm, expose_pdf_url, featured_rank, source, external_id) values (md5('property-13279')::uuid, md5('building-kurze-muehren-20-20095')::uuid, '13279', 'moderne-bueroraeume-mit-terrasse-in-bester-citylage-13279', 'Moderne Büroräume mit Terrasse in bester Citylage', 'Das moderne Büro- und Geschäftsgebäude befindet sich in bester Geschäftslage zwischen Mönckebergstraße und Binnenalster. Das Umfeld ist geprägt durch alle Geschäfte des täglichen …', 'Das moderne Büro- und Geschäftsgebäude befindet sich in bester Geschäftslage zwischen Mönckebergstraße und Binnenalster. Das Umfeld ist geprägt durch alle Geschäfte des täglichen Bedarfs sowie zahlreiche Cafés und Restaurants. Das moderne Bürogebäude wird über ein großzügiges Foyer mit zwei Personenaufzügen erschlossen. Zur aktuellen Ausstattung  der hellen Bürofläche zählen u.a. ein hochwertiger Teppichboden, akustisch wirksame Deckensegel, bodentiefe Fenster, Bodenkabelkanäle, außenliegender Sonnenschutz, ein Lüftungssystem, teilweise Glaselemente, getrennte WC-Einheiten und eine großzügige Pantry. Eine sonnige Terrasse zum Innenhof rundet das Angebot ab. PKW-Stellplätze können in der Tiefgarage angemietet werden.', 'buero-praxis', array['buero-praxis']::property_category[], 'buero', 'published', 'qm', 'zzgl. NK u. MwSt.', true, null, 'Dieses Mietangebot ist courtagefrei für den Mieter bei Abschluss eines Mietvertrages mit einer festen Mietlaufzeit von mindestens 5 Jahren.', array['balkon-terrasse', 'stellplaetze']::text[], 302, 413, 'https://www.buerohamburg.de/objects/pdf/BHI_13279.pdf', null, 'filemaker', '13279') on conflict (id) do nothing;
