insert into properties (id, building_id, reference_number, slug, title, teaser, description, category, categories, property_type, status, price_type, price_note, commission_free, commission_months, commission_note, features, area_range_min_sqm, area_range_max_sqm, expose_pdf_url, featured_rank, source, external_id) values (md5('property-24241')::uuid, md5('building-sonninstrasse-24-28-20097')::uuid, '24241', 'der-sonninhof-am-mittelkanal-24241', 'Der Sonninhof am Mittelkanal', 'Die ehemalige Schokoladenfabrik befindet sich zwischen den Elbrücken und der Alster und besticht durch seine Lage in der Nähe zum Mittelkanal. Die ÖPNV-Anbindung ist durch die …', 'Die ehemalige Schokoladenfabrik befindet sich zwischen den Elbrücken und der Alster und besticht durch seine Lage in der Nähe zum Mittelkanal. Die ÖPNV-Anbindung ist durch die fußläufig schnell erreichte S-Bahnstation Hammerbrook gesichert. Auch die Elbbrücken mit Anbindung an die A1 und A7 sind nur wenige Fahrminuten entfernt. Das imposante Gebäude verfügt über fünf Treppenhäuser und drei Aufzugsanlagen. Zur aktuellen Ausstattung der Bürofläche gehört u.a. Isolierverglasung, Fensterbankkanäle und außenliegender Sonnenschutz. PKW-Stellplätze können in der Tiefgarage angemietet werden. Die Innenbilder stammen aus einem Musterbüro im Objekt.', 'buero-praxis', array['buero-praxis']::property_category[], 'buero', 'published', 'qm', 'zzgl. NK u. MwSt.', false, 3, 'Dieses Mietangebot ist courtagepflichtig für den Mieter.*', array['stellplaetze']::text[], 259, 3000, 'https://www.buerohamburg.de/objects/pdf/BHI_24241.pdf', null, 'filemaker', '24241') on conflict (id) do nothing;
