insert into properties (id, building_id, reference_number, slug, title, teaser, description, category, categories, property_type, status, price_type, price_note, commission_free, commission_months, commission_note, features, area_range_min_sqm, area_range_max_sqm, expose_pdf_url, featured_rank, source, external_id) values (md5('property-18623')::uuid, md5('building-holzdamm-57-20099')::uuid, '18623', 'modernes-buerogebaeude-zwischen-hauptbahnhof-und-alster-18623', 'Modernes Bürogebäude zwischen Hauptbahnhof und Alster', 'Das hochwertige Bürogebäude befindet sich in verkehrsgünstiger Lage nahe der Außenalster im lebendigen Szeneviertel St. Georg. Der Hauptbahnhof mit allen Nah- und Fernverbindungen …', 'Das hochwertige Bürogebäude befindet sich in verkehrsgünstiger Lage nahe der Außenalster im lebendigen Szeneviertel St. Georg. Der Hauptbahnhof mit allen Nah- und Fernverbindungen sichert einen hervorragenden Anschluss an den ÖPNV. Im direkten Umfeld lädt die Lange Reihe mit vielseitigen Einkaufsmöglichkeiten, zahlreichen Cafés und Restaurants zum Bummeln ein. Die attraktive Mietfläche befindet sich im 1. Obergeschoss und verfügt u.a. über eine Klimaanlage, außenliegenden Sonnenschutz, Hohlraumboden, Teppichboden, ein Zugangskontrollsystem. Es können PKW-Stellplätze nach Rücksprache in der hauseigenen Tiefgarage angemietet werden. Diese Innenbilder sind beispielhaft gewählt und stammen aus einer ähnlichen Fläche im Objekt.', 'buero-praxis', array['buero-praxis']::property_category[], 'buero', 'published', 'qm', 'zzgl. NK u. MwSt.', true, null, 'Dieses Mietangebot ist courtagefrei für den Mieter bei Abschluss eines Mietvertrages mit einer festen Mietlaufzeit von mindestens 5 Jahren.', array['stellplaetze']::text[], 305, 940, 'https://www.buerohamburg.de/objects/pdf/BHI_18623.pdf', null, 'filemaker', '18623') on conflict (id) do nothing;
