insert into properties (id, building_id, reference_number, slug, title, teaser, description, category, categories, property_type, status, price_type, price_note, commission_free, commission_months, commission_note, features, area_range_min_sqm, area_range_max_sqm, expose_pdf_url, featured_rank, source, external_id) values (md5('property-3098')::uuid, md5('building-axel-springer-platz-2-20355')::uuid, '3098', 'helle-bueroetage-im-herzen-der-city-3098', 'Helle Büroetage im Herzen der City', 'Das Büro- und Geschäftsgebäude befindet sich im Herzen der Hamburger Innenstadt am Axel-Springer-Platz, nur wenige Meter vom Neuen Wall und den Großen Bleichen entfernt. Die U- …', 'Das Büro- und Geschäftsgebäude befindet sich im Herzen der Hamburger Innenstadt am Axel-Springer-Platz, nur wenige Meter vom Neuen Wall und den Großen Bleichen entfernt. Die U- und S-Bahnstationen Jungfernstieg und Stadthausbrücke sind fußläufig schnell erreicht und sichern einen hervorragenden Anschluss an den öffentlichen Nahverkehr. Das lebendige Umfeld ist geprägt durch vielseitige Einkaufsmöglichkeiten, diverse Passagen und zahlreichen gastronomischen Angeboten. Die aktuelle Ausstattung der hellen Büroetage im 3. Obergeschoss umfasst u.a. Parkettbodenbelag aus Eichenholz, Einbauschränke, Glastrennwände, glatt gespachtelte Decken und Wände, außenliegenden elektrischen Sonnenschutz, innenliegenden Blendschutz und eine bereits installierte CAT-5-Verkabelung sowie eine zweckmäßige Pantry. Darüber hinaus wurden die separaten Sanitäreinheiten komplett erneuert. Ein PKW-Stellplatz kann in der hauseigenen Tiefgarage angemietet werden.', 'buero-praxis', array['buero-praxis']::property_category[], 'buero', 'published', 'qm', 'zzgl. NK u. MwSt.', false, 3, 'Dieses Mietangebot ist courtagepflichtig für den Mieter.*', array['barrierefrei', 'stellplaetze']::text[], null, null, 'https://www.buerohamburg.de/objects/pdf/BHI_3098.pdf', null, 'filemaker', '3098') on conflict (id) do nothing;
