insert into properties (id, building_id, reference_number, slug, title, teaser, description, category, categories, property_type, status, price_type, price_note, commission_free, commission_months, commission_note, features, area_range_min_sqm, area_range_max_sqm, expose_pdf_url, featured_rank, source, external_id) values (md5('property-14826')::uuid, md5('building-theodorstrasse-42-90-22761')::uuid, '14826', 'schoene-lofts-in-hamburgs-westend-village-14826', 'Schöne Lofts in Hamburgs Westend Village', 'Das Westend Village befindet sich unmittelbar an der BAB 7 und ist ein außergewöhnlicher Ort zum Leben und Arbeiten. Das ehemalige Fabrikgelände der British American Tobacco aus …', 'Das Westend Village befindet sich unmittelbar an der BAB 7 und ist ein außergewöhnlicher Ort zum Leben und Arbeiten. Das ehemalige Fabrikgelände der British American Tobacco aus dem 19.Jahrhundert hat sich nach beendeter Restaurierung im Jahre 1998 in eine Anlage verwandelt, die durch ihr einmaliges Ambiente besticht. Das Areal bietet zahlreiche Serviceeinrichtungen wie ein Swimmingpool und eine ansprechende Gartenanlage. Der traditionelle Bestand wurde durch moderne Neubauten erweitert und verbindet heute alt und neu auf eine harmonische Weise. Die Innenbilder sind beispielhaft gewählt. PKW-Stellplätze können in der hauseigenen Tiefgarage angemietet werden.', 'buero-praxis', array['buero-praxis']::property_category[], 'buero', 'published', 'qm', 'zzgl. NK u. MwSt.', false, 3, 'Dieses Mietangebot ist courtagepflichtig für den Mieter.*', array['stellplaetze']::text[], 196, 4300, 'https://www.buerohamburg.de/objects/pdf/BHI_14826.pdf', null, 'filemaker', '14826') on conflict (id) do nothing;
