insert into properties (id, building_id, reference_number, slug, title, teaser, description, category, categories, property_type, status, price_type, price_note, commission_free, commission_months, commission_note, features, area_range_min_sqm, area_range_max_sqm, expose_pdf_url, featured_rank, source, external_id) values (md5('property-8609')::uuid, md5('building-grosse-elbstrasse-145a-f-22767')::uuid, '8609', 'das-elbkaihaus-loftflaeche-mit-balkon-und-direktem-elbbezug-8609', 'Das Elbkaihaus - Loftfläche mit Balkon und direktem Elbbezug', 'Das Elbkaihaus befindet sich in erster Elblinie mit herrlichem Blick über den Hafen. Der nahe gelegene Bahnhof Altona sichert eine gute Anbindung an den ÖPNV. Zahlreiche …', 'Das Elbkaihaus befindet sich in erster Elblinie mit herrlichem Blick über den Hafen. Der nahe gelegene Bahnhof Altona sichert eine gute Anbindung an den ÖPNV. Zahlreiche Einkaufsmöglichkeiten, Cafés und Restaurants sind fußläufig schnell erreicht. Die helle und transparent gestaltete Mietfläche ist unter anderem mit hochwertigem Fußbodenbelag ausgelegt und verfügt über außen liegenden Sonnenschutz, Trennwände in einer Stahl- Holzkonstruktion, einen Hohlraumboden, ein schlüssiges Beleuchtungssystem, separate WC-Bereiche, zwei kleine Kücheneinheiten, eine Sprinkler-  und eine Gegensprechanlage. Ein Highlight ist der kleine Balkon zur Elbseite mit beeindruckendem Panoramablick. PKW-Stellplätze können direkt am Objekt angemietet werden.', 'buero-praxis', array['buero-praxis']::property_category[], 'buero', 'published', 'qm', 'zzgl. NK u. MwSt.', true, null, 'Dieses Mietangebot ist courtagefrei für den Mieter bei Abschluss eines Mietvertrages mit einer festen Mietlaufzeit von mindestens 5 Jahren.', array['balkon-terrasse', 'barrierefrei', 'stellplaetze', 'wasserblick']::text[], 131, 498, 'https://www.buerohamburg.de/objects/pdf/BHI_8609.pdf', null, 'filemaker', '8609') on conflict (id) do nothing;
