insert into properties (id, building_id, reference_number, slug, title, teaser, description, category, categories, property_type, status, price_type, price_note, commission_free, commission_months, commission_note, features, area_range_min_sqm, area_range_max_sqm, expose_pdf_url, featured_rank, source, external_id) values (md5('property-20634')::uuid, md5('building-hammerbrookstrasse-90-20097')::uuid, '20634', 'modernes-bueroflaeche-im-herzen-der-citysued-20634', 'Modernes Bürofläche im Herzen der CitySüd', 'Das markante Büro- und Geschäftsgebäude befindet sich in verkehrsgünstiger Lage im Herzen der CitySüd. Die S-Bahn Station Hammerbrook ist nach wenigen Metern erreicht und sorgt …', 'Das markante Büro- und Geschäftsgebäude befindet sich in verkehrsgünstiger Lage im Herzen der CitySüd. Die S-Bahn Station Hammerbrook ist nach wenigen Metern erreicht und sorgt für eine sehr gute Anbindung, da die Station Hauptbahnhof nur eine Haltestelle entfernt liegt. Ein schneller Anschluss zu den Autobahnen A1 und A24 ist ebenfalls gegeben. Das direkte Umfeld ist geprägt durch zahlreiche gastronomische Angebote, welche durch einen zwei Mal die Woche statt findenden Wochenmarkt ergänzt werden.insert into rental_units (id, property_id, label, area_sqm, rent_per_sqm, rent_total_monthly, source, external_id) values (md5('unit-20634-1')::uuid, md5('property-20634')::uuid, 'Mietfläche', 311, 14.5, null, 'filemaker', '20634-1') on conflict (id) do nothing;
