insert into properties (id, building_id, reference_number, slug, title, teaser, description, category, categories, property_type, status, price_type, price_note, commission_free, commission_months, commission_note, features, area_range_min_sqm, area_range_max_sqm, expose_pdf_url, featured_rank, source, external_id) values (md5('property-21866')::uuid, md5('building-humboldtstrasse-57-22083')::uuid, '21866', 'barmbek-sued-helles-buero-in-zentraler-lage-21866', 'Barmbek-Süd: Helles Büro in zentraler Lage', 'Das sanierte Bürohaus befindet sich parallel zum Winterhuder Weg in einer ruhigen Seitenstraße unweit der Einkaufsmeile Hamburger Straße. Diverse Buslinien und die nahe gelegene …', 'Das sanierte Bürohaus befindet sich parallel zum Winterhuder Weg in einer ruhigen Seitenstraße unweit der Einkaufsmeile Hamburger Straße. Diverse Buslinien und die nahe gelegene U-Bahn Haltestelle Mundsburg gewährleisten eine gute ÖPNV Anbindung. Die helle Bürofläche befindet sich im 4. Obergeschoss und wird über einen Personenaufzug sowie ein modernes Treppenhaus erschlossen. Die Einheit befindet sich aktuell im veredelten Rohbau und wird in Absprache mit dem zukünftigen Mieter aufgeteilt und ausgestattet. PKW Stellplätze können nach Rücksprache in der hauseigenen Tiefgarage angemietet werden.', 'buero-praxis', array['buero-praxis']::property_category[], 'buero', 'published', 'qm', 'zzgl. NK u. MwSt.', true, null, 'Dieses Mietangebot ist courtagefrei für den Mieter bei Abschluss eines Mietvertrages mit einer festen Mietlaufzeit von mindestens 5 Jahren.', array['stellplaetze']::text[], null, null, 'https://www.buerohamburg.de/objects/pdf/BHI_21866.pdf', null, 'filemaker', '21866') on conflict (id) do nothing;
