insert into properties (id, building_id, reference_number, slug, title, teaser, description, category, categories, property_type, status, price_type, price_note, commission_free, commission_months, commission_note, features, area_range_min_sqm, area_range_max_sqm, expose_pdf_url, featured_rank, source, external_id) values (md5('property-19291')::uuid, md5('building-humboldtstrasse-67a-22085')::uuid, '19291', 'kompakte-bueroflaeche-in-ruhiger-hoflage-19291', 'Kompakte Bürofläche in ruhiger Hoflage', 'Das Bürohaus befindet sich parallel zum Winterhuder Weg in einer ruhigen Seitenstraße unweit des Einkaufszentrum Hamburger Meile. Eine Bushaltestelle sowie die U-Bahn Station …', 'Das Bürohaus befindet sich parallel zum Winterhuder Weg in einer ruhigen Seitenstraße unweit des Einkaufszentrum Hamburger Meile. Eine Bushaltestelle sowie die U-Bahn Station Mundsburg befinden sich in fußläufiger Entfernung. Die bereits ausgebaute Mietfläche ist über den hellen Eingangsbereich mit Personenfahrstuhl zu erreichen und u.a. ausgestattet mit einem Teppichboden, einer Küche, getrennten WC-Einheiten, Beleuchtungselementen, Fensterbankkabelkanal sowie elektrischen außenliegenden Sonnenschutz. Pkw-Stellplätze können zusätzlich nach Absprache auf dem Hof angemietet werden. Diese Innenbilder sind beispielhaft gewählt.', 'buero-praxis', array['buero-praxis']::property_category[], 'buero', 'published', 'qm', 'zzgl. NK u. MwSt.', true, null, 'Dieses Mietangebot ist courtagefrei für den Mieter bei Abschluss eines Mietvertrages mit einer festen Mietlaufzeit von mindestens 5 Jahren.', array['erdgeschoss', 'stellplaetze']::text[], null, null, 'https://www.buerohamburg.de/objects/pdf/BHI_19291.pdf', null, 'filemaker', '19291') on conflict (id) do nothing;
