insert into properties (id, building_id, reference_number, slug, title, teaser, description, category, categories, property_type, status, price_type, price_note, commission_free, commission_months, commission_note, features, area_range_min_sqm, area_range_max_sqm, expose_pdf_url, featured_rank, source, external_id) values (md5('property-23737')::uuid, md5('building-wendenstrasse-1b-20097')::uuid, '23737', 'repraesentatives-buero-im-zentraler-lage-von-hammerbrook-23737', 'Repräsentatives Büro im zentraler Lage von Hammerbrook', 'Das hochmoderne Büro- und Geschäftsgebäude befindet sich in exponierter Lage in der City Süd. Die Anbindung an den ÖPNV ist durch die S-Bahn-Station Hammerbrook als optimal zu …', 'Das hochmoderne Büro- und Geschäftsgebäude befindet sich in exponierter Lage in der City Süd. Die Anbindung an den ÖPNV ist durch die S-Bahn-Station Hammerbrook als optimal zu bezeichnen. Auch die Autobahnzubringer befinden sich in unmittelbarer Nähe. Diverse Einkaufsmöglichkeiten, eine Vielzahl an Cafés und Restaurants im direkten Umfeld erhöhen die Attraktivität dieses Standortes. Zwei begrünte Innenhöfe können als Erholungszone genutzt werden. Die lichtdurchflutete Bürofläche verfügt über Teppichfußboden, Bodenelektranten, Deckensegel, Sonnenschutz, eine Pantry und getrennte WC-Einheiten. Die weitere Aufteilung und Ausstattung erfolgt in enger Absprache mit dem neuen Mieter. Diese Bilder sind beispielhaft gewählt. PKW-Stelplätze können zusätzlich in der hauseigenen Tiefgarage angemietet werden.', 'buero-praxis', array['buero-praxis']::property_category[], 'buero', 'published', 'qm', 'zzgl. NK u. MwSt.', true, null, 'Dieses Mietangebot ist courtagefrei für den Mieter bei Abschluss eines Mietvertrages mit einer festen Mietlaufzeit von mindestens 5 Jahren.', array['stellplaetze']::text[], 324, 2327, 'https://www.buerohamburg.de/objects/pdf/BHI_23737.pdf', null, 'filemaker', '23737') on conflict (id) do nothing;
