insert into properties (id, building_id, reference_number, slug, title, teaser, description, category, categories, property_type, status, price_type, price_note, commission_free, commission_months, commission_note, features, area_range_min_sqm, area_range_max_sqm, expose_pdf_url, featured_rank, source, external_id) values (md5('property-24028')::uuid, md5('building-abc-strasse-15-20354')::uuid, '24028', 'modernes-buero-in-bester-innenstadtlage-24028', 'Modernes Büro in bester Innenstadtlage', 'Das moderne Neubauprojekt mit Feinputzfassade befindet sich in der ABC-Straße unweit der Binnenalster und dem Gänsemarkt im Herzen der Hamburger Innenstadt. Die ÖPNV Anbindung ist …', 'Das moderne Neubauprojekt mit Feinputzfassade befindet sich in der ABC-Straße unweit der Binnenalster und dem Gänsemarkt im Herzen der Hamburger Innenstadt. Die ÖPNV Anbindung ist durch die Bahnstationen Jungfernstieg und Gänsemarkt sowie verschiedene Buslinien sehr gut. Erstklassige Geschäfte, gute Restaurants und charmante Cafés unterstreichen den besonderen Flair dieser bevorzugten Lage. insert into rental_units (id, property_id, label, area_sqm, rent_per_sqm, rent_total_monthly, source, external_id) values (md5('unit-24028-1')::uuid, md5('property-24028')::uuid, 'Mietfläche', 327, 28, null, 'filemaker', '24028-1') on conflict (id) do nothing;
